/// A table's schema as one value: columns, primary key and indexes. Generated by `@Table`.
///
/// Holds type-erased `ColumnDescriptor`s; typed columns live in `Root.columns`.
public struct TableDescriptor<Root: Table>: Sendable {
    /// Columns in projection order, which is also the `INSERT` and decoding order.
    public let columns: [ColumnDescriptor]

    /// Primary key columns in declaration order; empty for a table without a key.
    public let primaryKey: [ColumnDescriptor]

    /// Indexes in order of first `@Index` mention. A composite index is several `@Index`
    /// attributes with the same name; its columns follow property order.
    public let indexes: [TableIndex<Root>]

    /// The table name quoted for SQL, computed once.
    public let quotedTableName: String

    /// The schema name quoted for SQL.
    public let quotedSchemaName: String

    public init(
        columns: [ColumnDescriptor],
        primaryKey: [ColumnDescriptor] = [],
        indexes: [TableIndex<Root>] = []
    ) {
        self.columns = columns
        self.primaryKey = primaryKey
        self.indexes = indexes
        self.quotedTableName = Root.tableName.quotedIdentifier
        self.quotedSchemaName = Root.schema.quotedSchemaName
    }
}
